// Fission products, lesson 3: the widget. #spectrum shows, at the chosen
// incident energy, the outgoing energies of prompt fission neutrons drawn
// through outram-mc-libs' own sampler (bars) against the exact law that
// sampler follows (line), both generated by lesson_fission_products into
// spectrum-data.js; and, as a second view, the mean and most probable
// outgoing energies against incident energy. Uses ../neutronics/lesson-kit.js.
//
// Nothing is computed per frame beyond drawing a precomputed histogram, so
// nothing needs a worker. The slider snaps to the generated grid.
(function () {
  "use strict";
  var L = window.Lesson, FE = window.FPEnergy, css = L.css, el = L.el;
  var D = function () { return window.SPECTRUM_DATA; };
  var E_LO = 1e-5, E_HI = 2e7;

  // The generated row nearest e (in log energy).
  function nearest(P, e) {
    var best = P.grid[0], bd = Infinity;
    P.grid.forEach(function (g) { var d = Math.abs(Math.log(g.e / e)); if (d < bd) { bd = d; best = g; } });
    return best;
  }
  function mev(x) { return (x / 1e6).toFixed(3) + " MeV"; }

  function spectrum(root) {
    var st = { parent: "U-235", view: "spectrum", logy: false, row: null, showSampled: true, showExact: true };
    function P() { return D()[st.parent]; }
    st.row = nearest(P(), FE.clamp(FE.initial(0.0253), E_LO, E_HI));

    var frame = new L.Frame(root, {
      reset: function () {},
      tick: function () { return false; },
      draw: function (ctx, w, h, zoom) {
        var fg = css("--fg", "#1d2125"), mut = css("--muted", "#5b636b"), acc = css("--accent", "#1f6f78"), hot = "#b85c38";
        ctx.font = "12px system-ui, sans-serif";
        // The first ~56 px are under the button bar; the legend sits below it.
        var x0 = 50, y0 = 92, pw = w - x0 - 14, ph = h - y0 - 96, R = st.row, Pp = P();
        if (st.view === "spectrum") {
          var wd = Pp.width, xmax = 10e6 / zoom;
          var X = function (e) { return x0 + Math.min(e / xmax, 1) * pw; };
          var dens = function (p) { return p / (wd / 1e6); }; // per MeV
          var pmax = 0; R.prob.forEach(function (p) { pmax = Math.max(pmax, dens(p)); });
          var top = pmax * 1.15;
          var Y = st.logy
            ? function (v) { var a = Math.log10(top) - 5, b = Math.log10(top); return y0 + ph * (1 - (Math.log10(Math.max(v, Math.pow(10, a))) - a) / (b - a)); }
            : function (v) { return y0 + ph * (1 - v / top); };
          ctx.strokeStyle = mut; ctx.lineWidth = 1; ctx.strokeRect(x0, y0, pw, ph);
          ctx.save(); ctx.beginPath(); ctx.rect(x0, y0, pw, ph); ctx.clip();
          var k;
          if (st.showSampled) {
            ctx.fillStyle = "rgba(47,127,216,0.45)";
            for (k = 0; k < R.counts.length; k++) {
              var v = dens(R.counts[k] / R.n);
              ctx.fillRect(X(k * wd), Y(v), Math.max(X((k + 1) * wd) - X(k * wd) - 1, 1), y0 + ph - Y(v));
            }
          }
          if (st.showExact) {
            ctx.strokeStyle = hot; ctx.lineWidth = 2; ctx.beginPath();
            for (k = 0; k < R.prob.length; k++) {
              var yy = Y(dens(R.prob[k]));
              if (k) ctx.lineTo(X(k * wd), yy); else ctx.moveTo(X(0), yy);
              ctx.lineTo(X((k + 1) * wd), yy);
            }
            ctx.stroke();
          }
          ctx.setLineDash([5, 4]); ctx.lineWidth = 1.5;
          ctx.strokeStyle = fg; ctx.beginPath(); ctx.moveTo(X(R.mean), y0); ctx.lineTo(X(R.mean), y0 + ph); ctx.stroke();
          ctx.strokeStyle = acc; ctx.beginPath(); ctx.moveTo(X(R.mode), y0); ctx.lineTo(X(R.mode), y0 + ph); ctx.stroke();
          ctx.setLineDash([]);
          ctx.restore();
          ctx.fillStyle = mut;
          for (var t = 0; t <= xmax / 1e6 + 1e-9; t += xmax > 4e6 ? 2 : 0.5) ctx.fillText(t + "", X(t * 1e6) - 4, y0 + ph + 14);
          ctx.fillText("outgoing neutron energy E′ (MeV)", x0 + pw - 200, y0 + ph + 28);
          ctx.fillStyle = hot; ctx.fillText("— exact law", 8, 66);
          ctx.fillStyle = "rgba(47,127,216,0.9)"; ctx.fillText("bars: " + R.n.toLocaleString("en") + " draws, the MC's sampler", 8, 82);
          ctx.fillStyle = fg; ctx.fillText("mean " + mev(R.mean), Math.min(X(R.mean) + 4, x0 + pw - 110), y0 + 30);
          ctx.fillStyle = acc; ctx.fillText("most probable " + mev(R.mode), Math.min(X(R.mode) + 4, x0 + pw - 150), y0 + 46);
        } else {
          // Mean and most probable outgoing energy against incident energy.
          // Linear in incident energy, 0 to 20 MeV: below 1 MeV nothing moves.
          var lx = function (e) { return x0 + Math.min(e / E_HI, 1) * pw; };
          var lo = Infinity, hi = 0;
          Pp.grid.forEach(function (g) { lo = Math.min(lo, g.mode); hi = Math.max(hi, g.mean); });
          lo = Math.max(lo * 0.8, 0); hi *= 1.08;
          var Yy = function (v) { return y0 + ph * (1 - (v - lo) / (hi - lo)); };
          ctx.strokeStyle = mut; ctx.lineWidth = 1; ctx.strokeRect(x0, y0, pw, ph);
          [["mean", fg], ["mode", acc]].forEach(function (s) {
            ctx.strokeStyle = s[1]; ctx.lineWidth = 2; ctx.beginPath();
            Pp.grid.forEach(function (g, i) { if (i) ctx.lineTo(lx(g.e), Yy(g[s[0]])); else ctx.moveTo(lx(g.e), Yy(g[s[0]])); });
            ctx.stroke();
            ctx.fillStyle = s[1];
            Pp.grid.forEach(function (g) { if (g.tab) { ctx.beginPath(); ctx.arc(lx(g.e), Yy(g[s[0]]), 3, 0, 2 * Math.PI); ctx.fill(); } });
          });
          ctx.fillStyle = mut;
          for (var dd = 0; dd <= 20; dd += 5) ctx.fillText(dd + "", lx(dd * 1e6) - 4, y0 + ph + 14);
          ctx.fillText("incident neutron energy (MeV)", x0 + pw - 180, y0 + ph + 28);
          for (var yv = Math.ceil(lo / 2.5e5) * 2.5e5; yv <= hi; yv += 2.5e5) ctx.fillText((yv / 1e6).toFixed(2), 8, Yy(yv) + 4);
          ctx.strokeStyle = hot; ctx.beginPath(); ctx.moveTo(lx(R.e), y0); ctx.lineTo(lx(R.e), y0 + ph); ctx.stroke();
          ctx.fillStyle = fg; ctx.fillText("— mean E′ (MeV)", 8, 66);
          ctx.fillStyle = acc; ctx.fillText("— most probable E′; dots: tabulated energies", 8, 82);
        }
        // The incident-energy strip: the evaluation's tabulated energies and the current one.
        var sy = h - 44, sx = function (e) { return x0 + (Math.log10(e) - Math.log10(E_LO)) / (Math.log10(E_HI) - Math.log10(E_LO)) * pw; };
        ctx.strokeStyle = mut; ctx.beginPath(); ctx.moveTo(x0, sy); ctx.lineTo(x0 + pw, sy); ctx.stroke();
        Pp.incident.forEach(function (e) { if (e >= E_LO && e <= E_HI) { ctx.beginPath(); ctx.moveTo(sx(e), sy - 6); ctx.lineTo(sx(e), sy + 6); ctx.stroke(); } });
        ctx.fillStyle = hot; ctx.beginPath(); ctx.arc(sx(R.e), sy, 5, 0, 2 * Math.PI); ctx.fill();
        ctx.fillStyle = mut; ctx.fillText("incident energy, log; ticks: tabulated", x0, sy + 20);
        var where = R.tab ? "a tabulated energy: one evaluated table, used as it is"
          : "between the tables at " + FE.label(Pp.incident[R.i]) + " and " + FE.label(Pp.incident[R.i + 1]) + "; the upper one is used with probability r = " + (R.r < 1e-3 ? R.r.toExponential(2) : R.r.toFixed(3));
        return st.parent + ", neutron at " + FE.label(R.e) + " (" + where + "). Mean " + mev(R.mean) + " (sampled " + mev(R.sum / R.n) + "), most probable " + mev(R.mode) + ".";
      },
      panel: function (body, redraw) {
        L.buttons(body, "Parent nucleus", Object.keys(D()).map(function (k) { return [k, k + " + n"]; }), st.parent, function (v) { st.parent = v; st.row = nearest(P(), st.row.e); sync(); redraw(); });
        L.buttons(body, "Show", [["spectrum", "Spectrum"], ["mean", "Mean vs energy"]], st.view, function (v) { st.view = v; redraw(); });
        var out = el("span", { "class": "w-val" }), g = el("label", { "class": "w-group" });
        g.append(el("span", { "class": "w-label" }, "Incident neutron energy (same as lesson 2)"), out);
        var s = el("input", { type: "range", min: 0, max: FE.STEPS, step: 1 });
        g.append(s); body.append(g);
        function sync() { s.value = FE.toPos(st.row.e, E_LO, E_HI); out.textContent = FE.label(st.row.e) + (st.row.tab ? " (tabulated)" : ""); link.href = "split-atoms.html?e=" + st.row.e; }
        s.oninput = function () { st.row = nearest(P(), FE.toEnergy(+s.value, E_LO, E_HI)); FE.remember(st.row.e); sync(); redraw(); };
        var row = el("div", { "class": "w-row" });
        [[0.0253, "thermal"], [5e5, "500 keV"], [2e6, "2 MeV"], [1.4e7, "14 MeV"]].forEach(function (q) {
          var b = el("button", { type: "button", "class": "w-opt" }, q[1]);
          b.onclick = function () { st.row = nearest(P(), q[0]); FE.remember(st.row.e); sync(); redraw(); };
          row.append(b);
        });
        body.append(el("span", { "class": "w-label" }, "Jump to"), row);
        L.toggle(body, "Sampled draws (bars)", st.showSampled, function (v) { st.showSampled = v; redraw(); });
        L.toggle(body, "Exact law (line)", st.showExact, function (v) { st.showExact = v; redraw(); });
        L.toggle(body, "Logarithmic density axis", st.logy, function (v) { st.logy = v; redraw(); });
        var link = el("a", { href: "split-atoms.html" }, "← The fission products at this energy (lesson 2)");
        body.append(el("p", { "class": "w-note" }, "The slider snaps to the energies the generator sampled: six per decade plus every tabulated one. Zoom in to see low outgoing energies."), link);
        sync();
      }
    });
    return frame;
  }

  // The table of means and most probable energies at the tabulated energies.
  function meanTable(node) {
    var body = node.querySelector("tbody"), Dd = D();
    Object.keys(Dd).forEach(function (name) {
      Dd[name].grid.forEach(function (g) {
        if (!g.tab) return;
        var tr = el("tr");
        tr.append(el("td", { "data-label": "Parent" }, name), el("td", { "data-label": "Incident energy" }, FE.label(g.e)),
          el("td", { "data-label": "Mean E′" }, mev(g.mean)), el("td", { "data-label": "Sampled mean" }, mev(g.sum / g.n)), el("td", { "data-label": "Most probable E′" }, mev(g.mode)));
        body.append(tr);
      });
    });
  }
  // Flags read from the tape, for the prose.
  function fillFlags() {
    var P = D()["U-235"];
    document.querySelectorAll("[data-sp]").forEach(function (n) {
      var k = n.getAttribute("data-sp");
      if (k === "lf") n.textContent = "LF = " + P.lf.join(", ") + ", NK = " + P.nk;
      if (k === "ntab") n.textContent = String(P.incident.length);
      if (k === "range") n.textContent = FE.label(P.incident[0]) + " to " + FE.label(P.incident[P.incident.length - 1]);
      if (k === "chances") n.textContent = P.chances.length ? "only MT " + P.chances.join(", ") : "none";
    });
  }

  L.widget("spectrum", spectrum);
  L.widget("mean-table", function (node) { meanTable(node); fillFlags(); });
})();
